# Source for q/ae-cm-peri-mass2.js: Cardiomyopathy + Pericardial disease + Masses (second batch).
CM="Cardiomyopathy"; P="Pericardial disease"; MS="Masses"
Q=[
# --- HCM ---
(CM,"Hypertrophic cardiomyopathy is most often inherited as:","Autosomal dominant mutations in sarcomere protein genes",["X-linked recessive","Mitochondrial only","Not inherited"],"First-degree relatives should be offered screening with echo and ECG.","F"),
(CM,"Which echo finding is a major risk factor for sudden death in HCM?","Maximal wall thickness of 30 mm or more",["Mild MR","Normal LV wall","Small LA"],"Other risk markers include unexplained syncope, family history, an apical aneurysm and EF under 50%.","F"),
(CM,"The LVOT CW Doppler signal in obstructive HCM typically looks:","Dagger-shaped, peaking late in systole",["Rounded with an early peak","Diastolic only","Flat"],"Valvular AS usually peaks earlier and is more rounded.","F"),
(CM,"The MR jet caused by SAM in obstructive HCM is usually directed:","Posteriorly and laterally, in mid to late systole",["Anteriorly toward the aorta","Centrally only","Into the RV"],"An anterior or central jet should prompt a look for primary mitral disease.","C"),
(CM,"Mid-cavity obstruction in HCM may be associated with:","An apical aneurysm with a paradoxical jet",["A large LA only","Aortic stenosis","Pericardial effusion"],"Use contrast to look for an aneurysm and thrombus at the apex.","C"),
(CM,"'End-stage' or 'burned-out' HCM is defined by:","LV systolic function falling to an EF under 50%",["More hypertrophy","An LVOT gradient over 100 mmHg","Normal function"],"The walls often thin and the LV may dilate.","C"),
(CM,"Patients taking a cardiac myosin inhibitor (such as mavacamten) for obstructive HCM need regular echo because:","The drug can reduce the EF, and dosing depends on EF and LVOT gradient",["It causes valve stenosis","It thickens the pericardium","It causes aortic dilation"],"Treatment is usually paused if the EF falls under 50%.","C"),
(CM,"Elongated mitral leaflets and anteriorly displaced papillary muscles in HCM contribute to:","SAM and LVOT obstruction",["Mitral stenosis","Aortic regurgitation","Tricuspid regurgitation"],"These features matter when planning septal reduction or mitral surgery.","C"),
(CM,"Concentric LV hypertrophy in a young person with ataxia and diabetes may point to:","Friedreich ataxia",["Marfan syndrome","Rheumatic fever","Kawasaki disease"],"Storage and neuromuscular disorders can mimic HCM.","C"),
# --- Amyloid and infiltrative ---
(CM,"The two most common types of cardiac amyloidosis are:","AL (light chain) and ATTR (transthyretin)",["AA and AB","Type 1 and type 2","Sarcoid and iron"],"ATTR is more common in older men; AL is related to plasma cell disorders.","F"),
(CM,"A classic clue to cardiac amyloidosis is thick LV walls on echo with:","Low QRS voltage on the ECG",["Very high voltage on ECG","A normal ECG always","Delta waves"],"In hypertension or HCM, thick walls usually come with high voltage.","F"),
(CM,"The relative apical sparing ratio in amyloidosis compares:","Average apical strain with the sum of basal and mid strain",["EF with LV mass","E with A","RV and LV size"],"A ratio over 1 supports amyloid.","C"),
(CM,"Besides thick LV walls, cardiac amyloidosis often shows:","Thick valves, a thick interatrial septum, thick RV free wall and biatrial enlargement",["A large dilated LV","Thin walls","A single atrium"],"A 'sparkling' myocardium is suggestive but not specific, especially with harmonic imaging.","F"),
(CM,"Restrictive cardiomyopathy typically shows:","Normal-sized ventricles, very large atria and low e′ velocities",["Dilated ventricles and small atria","Normal atria and high e′","A thick pericardium"],"In constriction, e′ is usually normal or high.","F"),
(CM,"'Annulus paradoxus' in constrictive pericarditis means:","E/e′ falls as filling pressures rise, opposite to the usual relationship",["E/e′ rises normally","The annulus moves backward","Septal e′ is low"],"Preserved septal e′ makes E/e′ falsely low.","C"),
(CM,"Endomyocardial fibrosis, common in tropical regions, typically causes:","Obliteration of one or both ventricular apices with thrombus and fibrosis",["Septal hypertrophy","Aortic dilation","Coronary aneurysms"],"It produces a restrictive filling pattern and AV valve regurgitation.","C"),
(CM,"Cardiac sarcoidosis classically causes thinning of the:","Basal anterior septum",["Apex only","RV free wall only","Atrial appendage"],"It can also cause heart block and aneurysms.","C"),
# --- DCM, oncology, other ---
(CM,"In cancer therapy follow-up, a relative fall in GLS of more than about 15% from baseline suggests:","Early (subclinical) cardiotoxicity",["Normal variation","Improved function","Pericarditis"],"Strain often falls before the EF does.","F"),
(CM,"Which drug's cardiotoxicity is often reversible after stopping treatment?","Trastuzumab",["Doxorubicin (anthracycline)","Radiation","Cyclophosphamide at high dose always"],"Anthracycline damage depends on cumulative dose and is often permanent.","C"),
(CM,"Echo follow-up after chest radiation for lymphoma should watch for:","Valve thickening, constriction, and premature coronary disease years later",["Only aortic dilation","Nothing","Only pulmonary stenosis"],"Radiation damage can appear decades after treatment.","F"),
(CM,"In LV noncompaction, the noncompacted to compacted layer ratio is measured:","At end-systole, usually in PSAX, with over 2:1 suggesting the diagnosis",["At end-diastole in PLAX only","In the RV","On M-mode of the aortic root"],"Deep recesses fill with color Doppler from the LV cavity.","C"),
(CM,"An ARVC major criterion on echo includes regional RV akinesia or dyskinesia plus:","An RVOT diameter of at least 32 mm in PLAX or a FAC of 33% or less",["A normal RV size","LV hypertrophy","Mitral prolapse"],"ARVC causes arrhythmias and sudden death in young people.","C"),
(CM,"Duchenne muscular dystrophy typically first affects the:","Inferolateral (posterolateral) LV wall",["Apex","RV only","Atrial septum"],"It progresses to dilated cardiomyopathy.","C"),
(CM,"In dilated cardiomyopathy with LBBB, CRT is used to:","Improve synchrony, and can reduce LV size and MR",["Thicken the walls","Treat aortic stenosis","Remove thrombus"],"Echo follow-up looks for a fall in LV volumes (reverse remodeling).","F"),
(CM,"Thyrotoxicosis typically causes which echo finding?","A hyperdynamic LV with high cardiac output",["A small hypokinetic heart","Pericardial constriction","Pulmonary stenosis"],"Untreated, it can lead to AF and heart failure.","F"),
# --- Pericardium anatomy and fluid ---
(P,"The pericardium consists of:","An outer fibrous layer and an inner serous layer with parietal and visceral parts",["Only one thin layer","Three muscle layers","The endocardium"],"Fluid lies between the parietal and visceral serous layers.","F"),
(P,"A normal pericardial space contains about:","15 to 50 mL of fluid",["None","200 to 300 mL","1 liter"],"A small amount of fluid lubricates heart motion.","F"),
(P,"The oblique sinus of the pericardium lies:","Behind the left atrium",["In front of the RV","Around the aortic arch","Inside the LV"],"Fluid here can look like a mass behind the LA.","C"),
(P,"The transverse sinus of the pericardium lies between the:","Great arteries in front and the atria behind",["LV and RV","Liver and diaphragm","Mitral leaflets"],"Fluid in it can mimic an abscess or mass near the aortic root.","C"),
(P,"Epicardial fat is usually told apart from effusion because fat:","Is slightly echogenic, granular, seen mostly anteriorly and moves with the heart",["Is always black and posterior","Collapses the RA","Shows color flow"],"Isolated anterior echo-free space is often fat.","F"),
(P,"Which tamponade finding is most specific?","RA collapse lasting more than one-third of the cardiac cycle",["Any brief RA notch","A small effusion","A small IVC"],"Brief RA inversion is sensitive but less specific.","C"),
(P,"In tamponade, tricuspid inflow velocity during inspiration usually:","Rises by more than about 40%",["Falls by 50%","Does not change","Disappears"],"Mitral inflow falls by more than about 25% on inspiration.","C"),
(P,"In tamponade, hepatic vein Doppler often shows:","Systolic-dominant flow with loss or reversal of diastolic flow in expiration",["Normal flow","Only diastolic flow","Continuous high-velocity flow"],"Filling happens mainly when ventricles empty in systole.","C"),
(P,"Beck's triad of tamponade is:","Low blood pressure, raised neck veins and muffled heart sounds",["Fever, rash and joint pain","Chest pain, cough and wheeze","Bradycardia, hypertension and irregular breathing"],"Echo confirms the diagnosis.","F"),
(P,"Electrical alternans on ECG in a large effusion is caused by:","The heart swinging back and forth within the fluid",["Atrial fibrillation","Bundle branch block","Digoxin"],"QRS height alternates from beat to beat.","F"),
(P,"A large effusion caused by hypothyroidism often does not cause tamponade because:","It builds up slowly, letting the pericardium stretch",["It is always small","It is always loculated","Hypothyroidism lowers RA pressure"],"Speed of fluid build-up matters more than volume.","F"),
(P,"After cardiac surgery, a loculated effusion behind the heart can cause tamponade by compressing the:","Left atrium or LV, which may not be seen well on TTE",["Aorta only","Pulmonic valve","Liver"],"TEE may be needed to see posterior clot.","F"),
(P,"In countries where TB is common, a major cause of constrictive pericarditis is:","Tuberculous pericarditis",["Rheumatic fever","Kawasaki disease","Marfan syndrome"],"In high-income countries, prior surgery, radiation and viral causes are more common.","F"),
(P,"Kussmaul's sign is:","A rise in neck vein pressure on inspiration, seen in constriction",["A fall in BP on inspiration","Chest pain on lying flat","A murmur heard on inspiration"],"Normally neck veins fall on inspiration.","C"),
(P,"In constrictive pericarditis, medial mitral annular e′ is usually:","Normal or high (often 9 cm/s or more)",["Very low (under 5 cm/s)","Absent","The same as A velocity"],"This helps separate constriction from restrictive cardiomyopathy.","C"),
(P,"During inspiration in constrictive pericarditis, the ventricular septum moves:","Toward the LV, because the RV fills more while total volume is fixed",["Toward the RV","Not at all","Out of the heart"],"This 'ventricular interdependence' is a key sign.","F"),
(P,"The definitive treatment for chronic constrictive pericarditis is:","Pericardiectomy",["Pericardiocentesis","Valve replacement","Pacemaker"],"Some early inflammatory cases improve with anti-inflammatory drugs.","F"),
(P,"First-line treatment of acute viral pericarditis usually includes:","NSAIDs (or aspirin) plus colchicine",["Surgery","Antibiotics only","Blood thinners"],"Colchicine lowers the risk of recurrence.","F"),
(P,"Postpericardiotomy syndrome is:","Pericardial inflammation and effusion weeks after cardiac surgery",["A congenital defect","A valve infection","A coronary spasm"],"It behaves like Dressler syndrome.","F"),
(P,"An echogenic, organized clot in the pericardial space after cardiac surgery or trauma suggests:","Hemopericardium",["Simple serous effusion","Epicardial fat","Pleural effusion"],"Clot may not drain with a needle.","F"),
(P,"Cancers that most often spread to the pericardium include:","Lung and breast cancer, lymphoma and melanoma",["Prostate only","Skin basal cell carcinoma","Thyroid nodules"],"Malignant effusions often come back after draining.","F"),
# --- Masses ---
(MS,"A myxoma usually looks like:","A mobile, gelatinous mass on a stalk, sometimes with lucent areas or calcium",["A flat mass with a wide base inside the RV","Thin filaments at the valve closure line","A cystic mass with daughter cysts"],"Surgical removal is the treatment because of embolism risk.","F"),
(MS,"Multiple, recurrent myxomas in unusual places in a young person suggest:","Carney complex",["Tuberous sclerosis","Marfan syndrome","Down syndrome"],"Carney complex also includes skin spots and endocrine tumors.","C"),
(MS,"A papillary fibroelastoma is classically:","Small (usually under 1 cm), on a short stalk, with frond-like edges that shimmer",["Large and fixed","A cyst","A calcified ring"],"It looks a bit like a sea anemone.","F"),
(MS,"Thin, hair-like strands seen on the closure line of the aortic valve in an older patient are most likely:","Lambl's excrescences",["Papillary fibroelastoma","Vegetations","Myxoma"],"They are degenerative and usually harmless. A fibroelastoma is a larger, frond-like mass on a stalk.","F"),
(MS,"Cardiac rhabdomyomas in infants are strongly associated with:","Tuberous sclerosis",["Down syndrome","Marfan syndrome","Turner syndrome"],"They are often multiple and many shrink over time.","F"),
(MS,"Angiosarcoma, the most common primary cardiac sarcoma, usually arises in the:","Right atrium, often with a pericardial effusion",["LV apex","Aortic valve","Pulmonary veins"],"Malignant tumors often invade with a broad base.","F"),
(MS,"Which cancer has the highest rate of spreading to the heart?","Melanoma",["Prostate cancer","Basal cell skin cancer","Thyroid cancer"],"Lung and breast cancer cause more cases overall because they are more common.","C"),
(MS,"Tumors that can grow up the IVC into the right atrium include:","Renal cell carcinoma, liver cancer and uterine leiomyoma",["Melanoma only","Basal cell cancer","Thyroid cancer"],"Follow the IVC from the subcostal view.","F"),
(MS,"A thrombus in transit (a long, snake-like mobile clot in the RA) needs:","Immediate notification of the physician as an emergency",["A routine report","No action","A repeat echo next year"],"It suggests a high-risk pulmonary embolism.","F"),
(MS,"Caseous calcification of the mitral annulus may be mistaken for:","A tumor or abscess",["A normal valve","A PFO","Pericardial fluid"],"It is a round mass with a bright rim and soft center, usually on the posterior annulus.","C"),
(MS,"A hydatid cyst of the heart (Echinococcus) typically appears as:","A cystic mass that may contain daughter cysts, often in the LV wall or septum",["A pedunculated LA mass","Shimmering fronds on the aortic valve","A thin line in the RA"],"Rupture can cause anaphylaxis or embolism. It is seen in regions where the parasite is common.","C"),
(MS,"A cardiac lipoma usually appears as:","A smooth, homogeneous, broad-based mass, often in the pericardium or atrial septum",["A mobile stalked mass","A thin filament","A calcified annulus"],"MRI confirms fat.","C"),
(MS,"A hiatal hernia can look like a mass compressing the:","Left atrium from behind",["RV free wall","Aortic arch","LV apex"],"Giving a carbonated drink shows swirling bubbles in the 'mass'.","C"),
(MS,"Vegetations differ from tumors because vegetations usually:","Sit on the upstream (low-pressure) side of valves and move irregularly with the valve",["Have a stalk on the septum","Are always fixed","Arise from the LA wall"],"Combine echo with the clinical picture (fever, blood cultures).","F"),
(MS,"Which imaging test best describes tissue type when a cardiac mass is found?","Cardiac MRI",["Chest X-ray","ECG","Exercise treadmill"],"MRI separates fat, fluid, thrombus and tumor.","F"),
(MS,"The moderator band is:","A normal muscle band in the RV carrying part of the conduction system",["A tumor","A thrombus","A pericardial cyst"],"It helps identify the morphologic right ventricle.","F"),
(MS,"A broad-based, invasive mass with pericardial effusion is more likely to be:","Malignant",["A myxoma","A fibroelastoma","A Lambl's excrescence"],"Benign tumors are usually well defined and stalked.","F"),
(MS,"A pericardial teratoma most often occurs in:","Infants or the fetus, usually next to the great arteries",["Elderly men","Pregnant women","Athletes"],"It can cause a large pericardial effusion.","C"),
]
